WITH filtered_accounts AS (SELECT * FROM accounts WHERE status IS NULL AND (customer_id IS NULL OR account_type = 'LOAN')), summary AS (SELECT QUARTER(opened_date) AS opened_quarter, account_type, MAX(balance) AS max_balance, COUNT(*) AS row_count FROM filtered_accounts GROUP BY QUARTER(opened_date), account_type) SELECT opened_quarter, account_type, max_balance, row_count FROM summary WHERE row_count < 8 ORDER BY row_count ASC
